import io.github.jan.supabase.postgrest.query.Columns
import io.ktor.client.call.body
import kotlinx.coroutines.delay
import kotlinx.coroutines.withTimeout
import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable
import kotlinx.serialization.json.JsonArray
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.JsonPrimitive
import kotlinx.serialization.json.buildJsonObject
import kotlinx.serialization.json.put

@Serializable
data class DiagnosticSessionInsert(@SerialName("user_id") val userId: String,@SerialName("vehicle_model_id") val vehicleModelId: String? = null,@SerialName("user_vehicle_id") val userVehicleId: String? = null,val complaint: String? = null,val language: String = "fr",val status: String = "created")
@Serializable
data class DiagnosticSession(val id: String,@SerialName("user_id") val userId: String? = null)
@Serializable
data class DiagnosticMeasurementInsert(@SerialName("session_id") val sessionId: String,@SerialName("pid_id") val pidId: String? = null,val name: String? = null,@SerialName("value_numeric") val valueNumeric: Double? = null,@SerialName("value_text") val valueText: String? = null,val unit: String? = null,val source: String = "obd")

class DiagnosticService {
    private val supabase = SupabaseClient.client
    private suspend fun ensureUserId(): String { supabase.auth.currentUserOrNull()?.let { return it.id }; runCatching { supabase.auth.signInAnonymously() }; return supabase.auth.currentUserOrNull()?.id ?: error("Unable to create a guest session") }
    suspend fun createSession(vehicleModelId: String?, userVehicleId: String?, complaint: String, language: String): DiagnosticSession { require(language in setOf("ar","fr","en")); val userId = ensureUserId(); return withTimeout(10_000) { supabase.from("diagnostic_sessions").insert(DiagnosticSessionInsert(userId,vehicleModelId,userVehicleId,complaint.ifBlank { null },language,"running")) { select(Columns.list("id","user_id")) }.decodeSingle() } }
    suspend fun saveMeasurements(sessionId: String, measurements: List<DiagnosticMeasurementInsert>) { if (measurements.isEmpty()) return; withTimeout(10_000) { supabase.from("diagnostic_measurements").insert(measurements) } }
    suspend fun diagnose(sessionId: String,codes: List<String> = emptyList(),symptoms: JsonObject = buildJsonObject {},measurements: JsonObject = buildJsonObject {},vehicle: JsonObject = buildJsonObject {},language: String = "fr"): JsonObject {
        require(language in setOf("ar","fr","en")) { "language must be ar, fr or en" }
        val normalizedCodes = codes.map { it.trim().uppercase() }.filter { it.matches(Regex("[PBCU][0-3][0-9A-F]{3}")) }.distinct()

        val payload = buildJsonObject { put("session_id",sessionId); put("codes",JsonArray(normalizedCodes.map { JsonPrimitive(it) }))
        put("complaint", vehicle["complaint"] ?: JsonPrimitive("")); put("symptoms",symptoms); put("measurements",measurements); put("vehicle",vehicle); put("language",language) }
        var last: Throwable? = null
        repeat(3) { attempt ->
            try {
                return withTimeout(45_000) {
                    val response = supabase.functions.invoke(function = "diagnose", body = payload)
                    val body = response.body<JsonObject>()
                    if (body["error"] != null || body["ok"]?.toString() == "false") error(body["error"]?.toString() ?: "Diagnostic service error")
                    body
                }
            } catch (e: Throwable) { last = e; Log.e("CarDiag-Diagnostic","diagnose attempt ${attempt + 1} failed",e); if (attempt < 2) delay(800L * (attempt + 1)) }
        }
        throw IllegalStateException("Diagnostic AI unavailable: ${last?.message ?: "unknown error"}", last)
    }
    suspend fun runDiagnostic(vehicleModelId: String?,userVehicleId: String?,complaint: String,language: String,codes: List<String> = emptyList(),symptoms: JsonObject = buildJsonObject {},measurements: JsonObject = buildJsonObject {},vehicle: JsonObject = buildJsonObject {}): JsonObject { val session = createSession(vehicleModelId,userVehicleId,complaint,language); return diagnose(session.id,codes,symptoms,measurements,vehicle,language) }
}
package dz.cardiag.app.core

import android.annotation.SuppressLint
import android.bluetooth.BluetoothAdapter
import android.bluetooth.BluetoothDevice
import android.bluetooth.BluetoothSocket
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.delay
import kotlinx.coroutines.withContext
import java.io.IOException
import java.util.UUID

/** Production-oriented Bluetooth Classic ELM327 transport. Hardware support remains adapter/vehicle dependent. */
class ObdService {
    companion object { private val SPP_UUID: UUID = UUID.fromString("00001101-0000-1000-8000-00805F9B34FB") }
    @Suppress("DEPRECATION") private val adapter: BluetoothAdapter? = BluetoothAdapter.getDefaultAdapter()
    private var socket: BluetoothSocket? = null
    private var lastDevice: BluetoothDevice? = null
    @Volatile private var detectedProtocol: String = "unknown"
    @Volatile private var connected = false

    fun isAvailable(): Boolean = adapter != null
    fun isConnected(): Boolean = connected && socket?.isConnected == true
    fun protocol(): String = detectedProtocol
    @SuppressLint("MissingPermission") fun bondedDevices(): List<BluetoothDevice> = adapter?.bondedDevices?.sortedBy { it.name ?: it.address }?.toList().orEmpty()

    @SuppressLint("MissingPermission")
    suspend fun connect(device: BluetoothDevice): String = withContext(Dispatchers.IO) {
        disconnect(); require(adapter?.isEnabled == true) { "Bluetooth is disabled" }
        lastDevice = device
        val s = device.createRfcommSocketToServiceRecord(SPP_UUID); socket = s
        try {
            s.connect()
            command("ATZ", 3000); command("ATE0"); command("ATL0"); command("ATS0"); command("ATH0"); command("ATAT1"); command("ATSP0", 2500)
            detectedProtocol = parseProtocol(command("ATDPN", 2500))
            connected = true
            "Connected • ${device.name ?: device.address} • $detectedProtocol"
        } catch (e: Exception) { disconnect(); throw IOException("Unable to connect to ELM327 adapter", e) }
    }

    suspend fun reconnect(): String { val d = lastDevice ?: error("No previous OBD adapter"); repeat(2) { try { return connect(d) } catch (_: Exception) { delay(400) } }; error("Unable to reconnect to ELM327 adapter") }
    suspend fun readTroubleCodes(): List<String> = ObdParser.parseDtc(command("03", 4000))
    suspend fun readPendingTroubleCodes(): List<String> = ObdParser.parseDtc(command("07", 4000))
    suspend fun readPermanentTroubleCodes(): List<String> = ObdParser.parseDtc(command("0A", 4000))
    suspend fun clearTroubleCodes(): String = command("04", 5000)
    suspend fun readRpm(): Double? = ObdParser.parseRpm(command("010C"))
    suspend fun readCoolantTemperature(): Double? = ObdParser.parseCoolantCelsius(command("0105"))
    suspend fun readVehicleSpeedKmh(): Double? = ObdParser.parseSpeed(command("010D"))
    suspend fun readIntakeTemperature(): Double? = ObdParser.parseIntakeTemperature(command("010F"))
    suspend fun readThrottlePosition(): Double? = ObdParser.parsePercent(command("0111"))
    suspend fun readMaf(): Double? = ObdParser.parseMaf(command("0110"))
    suspend fun readMap(): Double? = ObdParser.parseMap(command("010B"))
    suspend fun readFuelLevel(): Double? = ObdParser.parsePercent(command("012F"))
    suspend fun readEngineLoad(): Double? = ObdParser.parsePercent(command("0104"))
    suspend fun readTimingAdvance(): Double? = ObdParser.parseTimingAdvance(command("010E"))
    suspend fun readBatteryVoltage(): Double? = ObdParser.parseVoltage(command("0142"))
    suspend fun readSupportedPids01_20(): String = command("0100", 3000)
    suspend fun readSupportedPids21_40(): String = command("0120", 3000)
    suspend fun readSupportedPids41_60(): String = command("0140", 3000)

    suspend fun readSupportedPids(): Set<Int> {
        val supported = mutableSetOf<Int>()
        supported += ObdParser.parseSupportedPids(readSupportedPids01_20(), 0x00)
        runCatching { supported += ObdParser.parseSupportedPids(readSupportedPids21_40(), 0x20) }
        runCatching { supported += ObdParser.parseSupportedPids(readSupportedPids41_60(), 0x40) }
        return supported
    }

    suspend fun readVehicleInfoVin(): String = command("0902", 5000)
    suspend fun readEcuName(): String = command("090A", 5000)
    suspend fun readEcuInfo(): String = readEcuName()
    suspend fun readFreezeFrameRaw(): String = command("02", 5000)
    suspend fun readFreezeFrameCodes(): List<String> = ObdParser.parseDtc(readFreezeFrameRaw(), 0x42)
    suspend fun readReadinessRaw(): String = command("0101", 3000)
    suspend fun readReadiness(): ReadinessStatus = ObdParser.parseReadiness(readReadinessRaw())
    suspend fun readMilStatus(): Boolean? = ObdParser.parseMilStatus(readReadinessRaw())
    suspend fun adapterInfo(): String = command("ATI", 2500)
    suspend fun adapterProtocol(): String = command("ATDPN", 2500).let(::parseProtocol)
    suspend fun readMode01Pid(pid: String): String = command("01${pid.trim().uppercase().padStart(2, '0')}", 2500)
    suspend fun scanSupportedPids(): Map<Int, Boolean> = readSupportedPids().let { supported -> (1..0x60).associateWith { it in supported } }

    suspend fun command(command: String, timeoutMs: Long = 1800): String = withContext(Dispatchers.IO) {
        val normalized = command.trim().uppercase()
        require(normalized.matches(Regex("[0-9A-Z]+"))) { "Invalid ELM327 command" }
        val s = socket ?: error("OBD adapter is not connected")
        try {
            s.outputStream.write((normalized + "\r").toByteArray(Charsets.US_ASCII)); s.outputStream.flush()
            val deadline = System.currentTimeMillis() + timeoutMs
            val buffer = StringBuilder(); val bytes = ByteArray(1024)
            while (System.currentTimeMillis() < deadline) {
                if (s.inputStream.available() > 0) {
                    val n = s.inputStream.read(bytes)
                    if (n > 0) { buffer.append(String(bytes, 0, n, Charsets.US_ASCII)); if (buffer.contains(">")) break }
                } else Thread.sleep(20)
            }
            ObdParser.normalize(buffer.toString()).ifBlank { error("ELM327 timeout: $normalized") }
        } catch (e: Exception) {
            connected = false; try { s.close() } catch (_: Exception) {}; socket = null
            throw IOException("ELM327 command failed: $normalized", e)
        }
    }

    fun disconnect() { connected = false; try { socket?.close() } catch (_: IOException) {}; socket = null }
    private fun parseProtocol(raw: String): String = when (raw.trim().uppercase().removePrefix("A")) {
        "0" -> "AUTO"; "1" -> "SAE J1850 PWM"; "2" -> "SAE J1850 VPW"; "3" -> "ISO 9141-2"
        "4" -> "ISO 14230-4 KWP (5-baud)"; "5" -> "ISO 14230-4 KWP (fast)"; "6" -> "ISO 15765-4 CAN 11/500"
        "7" -> "ISO 15765-4 CAN 29/500"; "8" -> "ISO 15765-4 CAN 11/250"; "9" -> "ISO 15765-4 CAN 29/250"
        else -> raw.ifBlank { "unknown" }
    }
}
package dz.cardiag.app.core

/** Pure OBD-II/ELM327 response parser. Kept side-effect free so it can be exhaustively unit tested. */
object ObdParser {
    private val HEX_TOKEN = Regex("[0-9A-F]{2,}")

    fun normalize(raw: String): String = raw
        .replace('\r', '\n')
        .replace(">", "")
        .lines()
        .map { it.trim() }
        .filter { it.isNotEmpty() }
        .filterNot { it.equals("SEARCHING...", true) || it.equals("NO DATA", true) || it.equals("OK", true) }
        .joinToString(" ")
        .uppercase()

    private fun bytes(raw: String): List<Int> = normalize(raw).split(Regex("\\s+"))
        .flatMap { token ->
            if (HEX_TOKEN.matches(token) && token.length % 2 == 0) {
                token.chunked(2).mapNotNull { it.toIntOrNull(16) }
            } else emptyList()
        }

    private fun response(bytes: List<Int>, mode: Int, pid: Int): Int =
        bytes.windowed(2).indexOfFirst { it[0] == mode + 0x40 && it[1] == pid }

    fun parseRpm(raw: String): Double? {
        val b = bytes(raw); val i = response(b, 1, 0x0C)
        return if (i >= 0 && i + 3 < b.size) (b[i + 2] * 256 + b[i + 3]) / 4.0 else null
    }

    fun parseCoolantCelsius(raw: String): Double? {
        val b = bytes(raw); val i = response(b, 1, 0x05)
        return if (i >= 0 && i + 2 < b.size) b[i + 2] - 40.0 else null
    }

    fun parseSpeed(raw: String): Double? {
        val b = bytes(raw); val i = response(b, 1, 0x0D)
        return if (i >= 0 && i + 2 < b.size) b[i + 2].toDouble() else null
    }

    fun parseIntakeTemperature(raw: String): Double? {
        val b = bytes(raw); val i = response(b, 1, 0x0F)
        return if (i >= 0 && i + 2 < b.size) b[i + 2] - 40.0 else null
    }

    fun parsePercent(raw: String): Double? {
        val b = bytes(raw)
        val i = b.windowed(2).indexOfFirst { it[0] == 0x41 && it[1] in setOf(0x04, 0x11, 0x2F) }
        return if (i >= 0 && i + 2 < b.size) b[i + 2] * 100.0 / 255.0 else null
    }

    fun parseMaf(raw: String): Double? {
        val b = bytes(raw); val i = response(b, 1, 0x10)
        return if (i >= 0 && i + 3 < b.size) (b[i + 2] * 256 + b[i + 3]) / 100.0 else null
    }

    fun parseMap(raw: String): Double? {
        val b = bytes(raw); val i = response(b, 1, 0x0B)
        return if (i >= 0 && i + 2 < b.size) b[i + 2].toDouble() else null
    }

    fun parseTimingAdvance(raw: String): Double? {
        val b = bytes(raw); val i = response(b, 1, 0x0E)
        return if (i >= 0 && i + 2 < b.size) b[i + 2] / 2.0 - 64.0 else null
    }

    fun parseVoltage(raw: String): Double? {
        val b = bytes(raw); val i = response(b, 1, 0x42)
        return if (i >= 0 && i + 3 < b.size) (b[i + 2] * 256 + b[i + 3]) / 1000.0 else null
    }

    fun parseDtc(raw: String, mode: Int? = null): List<String> {
        val b = bytes(raw)
        val modes = mode?.let { listOf(it) } ?: listOf(0x43, 0x47, 0x4A)
        val startMode = modes.firstOrNull { it in b } ?: return emptyList()
        val i = b.indexOf(startMode)
        return b.drop(i + 1).chunked(2)
            .takeWhile { it.size == 2 && !(it[0] == 0 && it[1] == 0) }
            .map { pair ->
                val value = (pair[0] shl 8) or pair[1]
                val letter = when ((value shr 14) and 3) { 0 -> 'P'; 1 -> 'C'; 2 -> 'B'; else -> 'U' }
                "$letter${(value shr 12) and 3}${value.toString(16).uppercase().padStart(4, '0').takeLast(3)}"
            }
            .distinct()
    }

    /** Decode a Mode 01 Supported-PIDs bitmap. base is 0x00, 0x20 or 0x40. */
    fun parseSupportedPids(raw: String, base: Int): Set<Int> {
        require(base in setOf(0x00, 0x20, 0x40)) { "Supported PID base must be 0x00, 0x20 or 0x40" }
        val b = bytes(raw)
        val i = response(b, 1, base)
        if (i < 0 || i + 5 >= b.size) return emptySet()
        val mask = (b[i + 2] shl 24) or (b[i + 3] shl 16) or (b[i + 4] shl 8) or b[i + 5]
        return (1..32).filter { mask and (1 shl (32 - it)) != 0 }.map { base + it }.toSet()
    }

    fun parseMilStatus(raw: String): Boolean? {
        val b = bytes(raw); val i = response(b, 1, 0x01)
        return if (i >= 0 && i + 2 < b.size) (b[i + 2] and 0x80) != 0 else null
    }

    fun parseReadiness(raw: String): ReadinessStatus {
        val b = bytes(raw); val i = response(b, 1, 0x01)
        if (i < 0 || i + 6 >= b.size) return ReadinessStatus(null, null, normalize(raw))
        val mil = (b[i + 2] and 0x80) != 0
        val statusByteB = b[i + 3]
        val statusByteC = b[i + 4]
        return ReadinessStatus(mil, statusByteB == 0 && statusByteC == 0, normalize(raw))
    }
}
package dz.cardiag.app.core

import io.github.jan.supabase.auth.auth
import io.github.jan.supabase.auth.providers.builtin.Email
import io.github.jan.supabase.auth.user.UserInfo

class AuthService {
    private val auth get() = SupabaseClient.client.auth

    val currentUser: UserInfo?
        get() = auth.currentSessionOrNull()?.user

    suspend fun ensureGuest(): UserInfo {
        currentUser?.let { return it }
        auth.signInAnonymously()
        return auth.currentSessionOrNull()?.user ?: error("Guest session could not be created")
    }

    suspend fun signUp(email: String, password: String) {
        val normalized = email.trim()
        require(normalized.contains("@")) { "Valid email is required" }
        require(password.length >= 8) { "Password must contain at least 8 characters" }
        auth.signUpWith(Email) {
            this.email = normalized
            this.password = password
        }
    }

    suspend fun signIn(email: String, password: String) {
        val normalized = email.trim()
        require(normalized.contains("@")) { "Valid email is required" }
        require(password.isNotBlank()) { "Password is required" }
        auth.signInWith(Email) {
            this.email = normalized
            this.password = password
        }
    }

    suspend fun signOut() = auth.signOut()
}

