@Composable
private fun SymptomCategoryChipRow(current: SymptomCategory, onSelect: (SymptomCategory) -> Unit) {
    val categories = listOf(
        SymptomCategory.ENGINE to "Engine",
        SymptomCategory.ELECTRICAL to "Electrical",
        SymptomCategory.BRAKES to "Brakes",
        SymptomCategory.AIRBAG to "Airbag",
        SymptomCategory.TRANSMISSION to "Transmission",
        SymptomCategory.COOLING to "Cooling",
        SymptomCategory.EMISSIONS to "DPF/EGR",
        SymptomCategory.OTHER to "Other"
    )
    Column(verticalArrangement = Arrangement.spacedBy(6.dp)) {
        categories.chunked(3).forEach { row ->
            Row(horizontalArrangement = Arrangement.spacedBy(6.dp)) {
                row.forEach { (cat, label) ->
                    AssistChip(
                        onClick = { onSelect(cat) },
                        label = { Text(label) },
                        colors = if (cat == current) AssistChipDefaults.assistChipColors(containerColor = MaterialTheme.colorScheme.primaryContainer) else AssistChipDefaults.assistChipColors()
                    )
                }
            }
        }
    }
}

