    @Test fun decodesWmiRegionAndYear() {
        val d = VinDecoder.decode("VF1AAAAA41BBBBBBB")
        assertEquals("VF1", d.wmi)
        assertEquals("Europe", d.region)
        assertEquals(2031, d.modelYear)
        assertTrue(d.checkDigitValid)
        assertTrue(d.valid)
    }
