@Composable
fun SymptomDiagnosisScreen(
    padding: PaddingValues,
    arabic: Boolean,
    hasVehicle: Boolean,
    onBack: () -> Unit,
    onOpenAi: () -> Unit
) {
    val scope = rememberCoroutineScope()
    var complaint by remember { mutableStateOf("") }
    var whenHappens by remember { mutableStateOf("") }
    var engineState by remember { mutableStateOf("") }
    var category by remember { mutableStateOf(SymptomCategory.OTHER) }
    var severity by remember { mutableStateOf(SymptomSeverity.MODERATE) }
    var loading by remember { mutableStateOf(false) }
    var summary by remember { mutableStateOf<String?>(null) }
    var error by remember { mutableStateOf<String?>(null) }
    val context = LocalContext.current

    LazyColumn(
        modifier = Modifier.fillMaxSize().padding(padding),
        contentPadding = PaddingValues(bottom = 24.dp),
        verticalArrangement = Arrangement.spacedBy(10.dp)
    ) {
